from packaging.requirements import Requirement
from typing import Dict, List, Union, Any


def lookup_dependency_group(dependency_groups: Dict[str, List[Union[str, Dict[str, str]]]], group: str) -> List[Dict[str, Any]]:
    """
    Lookup a group name, returning the parsed dependency data for that group.
    This will not resolve includes.

    :param dependency_groups: Mapping of dependency group names to their dependencies
    :param group: the name of the group to lookup
    :example: lookup_dependency_group({"dev": ["pytest", "black"]}, "dev") -> [{"name": "pytest"}, {"name": "black"}]
    """
    try:
        resolver = DependencyGroupResolver(dependency_groups)
        result = resolver.lookup(group)

        parsed_deps = []
        for dep in result:
            if isinstance(dep, Requirement):
                parsed_deps.append({
                    "name": str(dep.name),
                    "specifier": str(dep.specifier) if dep.specifier else "",
                    "extras": list(dep.extras) if dep.extras else []
                })
            else:
                # For DependencyGroupInclude, we'd need more specific handling
                # but since we're just returning parsed data, we'll represent it generically
                parsed_deps.append({
                    "include": str(dep)
                })

        return parsed_deps
    except Exception as e:
        raise ValueError(f"Failed to lookup dependency group {group!r}: {str(e)}")
